import{_ as a,o as e,c as l,ag as i}from"./chunks/framework.CvgP6Fyv.js";const s="/bima/web-page-light.svg",o="/bima/web-page-dark.svg",r="/bima/shopping-light.svg",n="/bima/shopping-dark.svg",d="/bima/mail-light.svg",c="/bima/mail-dark.svg",h="/bima/wechat-light.svg",g="/bima/wechat-dark.svg",S=JSON.parse('{"title":"关于我们","description":"","frontmatter":{},"headers":[{"level":1,"title":"关于我们","slug":"关于我们","link":"#关于我们","children":[{"level":2,"title":"核心能力","slug":"核心能力","link":"#核心能力","children":[]},{"level":2,"title":"业务服务","slug":"业务服务","link":"#业务服务","children":[{"level":3,"title":"CAS Overlay 单点登录系统","slug":"cas-overlay-单点登录系统","link":"#cas-overlay-单点登录系统","children":[]},{"level":3,"title":"Smart Scaffold 智能中间件集成验证脚手架","slug":"smart-scaffold-智能中间件集成验证脚手架","link":"#smart-scaffold-智能中间件集成验证脚手架","children":[]},{"level":3,"title":"Keycloak Sandbox 双沙箱环境","slug":"keycloak-sandbox-双沙箱环境","link":"#keycloak-sandbox-双沙箱环境","children":[]}]},{"level":2,"title":"技术支持服务","slug":"技术支持服务","link":"#技术支持服务","children":[]},{"level":2,"title":"联系我们","slug":"联系我们","link":"#联系我们","children":[]}]}],"relativePath":"bima/关于我们.md","filePath":"bima/关于我们.md"}'),f={name:"bima/关于我们.md"};function p(m,t,y,b,k,v){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="关于我们" tabindex="-1">关于我们 <a class="header-anchor" href="#关于我们" aria-label="Permalink to &quot;关于我们&quot;">​</a></h1><p>北京必码科技工作室（简称&quot;必码&quot;），专注于开源项目定制开发与技术服务。我们秉承&quot;只写必要的代码&quot;理念，围绕<strong>企业级身份认证</strong>与<strong>微服务架构</strong>两大核心方向，提供轻量化、可落地的技术解决方案。</p><p>我们坚持&quot;小而精、专而深&quot;的服务原则，聚焦开源生态，专注技术落地。凭借丰富的开源二次开发经验，从需求分析到交付运维，全程细致跟进。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>CAS Overlay 单点登录系统</strong>：企业级定制开发，支持 WAR 转 JAR 架构升级、JDBC + LDAP 双源认证、OAuth 2.0 + OIDC 协议、Redis 分布式票据、安全加固、前端品牌定制、Docker / CI/CD 容器化部署</li><li><strong>Keycloak Sandbox 双沙箱</strong>：一站式 Keycloak SPI 开发环境，支持多版本 Keycloak、双沙箱环境（Docker 版 + Release 版）、SPI 一键打包发布、内置 SPI 开发示例</li><li><strong>Keycloak Extension 扩展开发</strong>：SPI 用户存储扩展（支持多种数据库）、事件监听器扩展（支持多种消息队列）、国密算法扩展（SM2/SM3/SM4）</li><li><strong>AI 能力集成</strong>：Ollama 本地大模型、OpenAI API、SSE 流式聊天、Chroma 文本向量嵌入等全场景 AI 能力</li><li><strong>Smart Scaffold 智能中间件集成验证脚手架</strong>：一站式微服务脚手架，覆盖 Spring Boot / Dubbo / Spring Cloud 三种架构，集成 MyBatis、Elasticsearch、Kafka、MongoDB、RabbitMQ、Redis、RocketMQ、LDAP 八大中间件</li><li><strong>容器化部署</strong>：Docker 多阶段构建、Jenkins CI/CD 自动化部署、Kubernetes 编排等容器化部署方案</li></ul><h2 id="业务服务" tabindex="-1">业务服务 <a class="header-anchor" href="#业务服务" aria-label="Permalink to &quot;业务服务&quot;">​</a></h2><h3 id="cas-overlay-单点登录系统" tabindex="-1">CAS Overlay 单点登录系统 <a class="header-anchor" href="#cas-overlay-单点登录系统" aria-label="Permalink to &quot;CAS Overlay 单点登录系统&quot;">​</a></h3><p>基于 Apereo CAS 提供企业级定制开发服务，解决多系统统一身份认证问题。</p><p><strong>核心能力：</strong> WAR 转 JAR 现代化升级 · JDBC + LDAP 双源认证 · OAuth 2.0 + OIDC · JWT AccessToken · Redis 分布式票据 · 安全加固 · 前端品牌定制 · Docker / CI/CD</p><p><a href="/dev/cas-overlay/">查看 CAS Overlay</a> · <a href="/tech/cas-overlay/">阅读 CAS Overlay 深度解析系列</a></p><h3 id="smart-scaffold-智能中间件集成验证脚手架" tabindex="-1">Smart Scaffold 智能中间件集成验证脚手架 <a class="header-anchor" href="#smart-scaffold-智能中间件集成验证脚手架" aria-label="Permalink to &quot;Smart Scaffold 智能中间件集成验证脚手架&quot;">​</a></h3><p>一站式微服务项目脚手架，同一业务场景在三种架构下的完整实现，为架构选型提供可直接对比的参考。</p><p><strong>核心能力：</strong> 8 大中间件集成验证 · AI 全场景集成 · OAuth 2.0 + OIDC · 多数据源动态配置 · 全覆盖测试用例 · Docker / CI/CD</p><p><a href="/dev/smart-scaffold/">查看 Smart Scaffold</a> · <a href="/tech/smart-scaffold/">阅读 Smart Scaffold 深度解析系列</a></p><h3 id="keycloak-sandbox-双沙箱环境" tabindex="-1">Keycloak Sandbox 双沙箱环境 <a class="header-anchor" href="#keycloak-sandbox-双沙箱环境" aria-label="Permalink to &quot;Keycloak Sandbox 双沙箱环境&quot;">​</a></h3><p>Keycloak Sandbox 是一个预置了多种扩展功能的 Keycloak SPI 开发环境（Docker /Release 双沙箱），包含用户存储扩展、事件监听器、国密算法等预置功能，可直接体验各类扩展能力。</p><p><strong>预置能力：</strong> 多数据库用户存储 · 事件监听器扩展 · 国密算法（SM2/SM3/SM4） · 自定义主题 · REST API 扩展</p><p><a href="/dev/keycloak-sandbox/">查看 Keycloak Sandbox</a> · <a href="/tech/keycloak-sandbox/">阅读 Keycloak Sandbox 深度解析系列</a></p><h2 id="技术支持服务" tabindex="-1">技术支持服务 <a class="header-anchor" href="#技术支持服务" aria-label="Permalink to &quot;技术支持服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">服务类型</th><th style="text-align:left;">服务范围</th><th style="text-align:left;">收费标准</th><th style="text-align:left;">备 注</th></tr></thead><tbody><tr><td style="text-align:left;">软件技术支持服务</td><td style="text-align:left;">本店软件售后服务的相关咨询、软件本身疑问解答及问题排查解决等服务。</td><td style="text-align:left;">免费（7日内）</td><td style="text-align:left;">限软件本身相关问题</td></tr><tr><td style="text-align:left;">在线技术支持服务</td><td style="text-align:left;">软件本身相关及周边问题，包括但不限于开发工具使用、软件部署、各种配置等疑问解答及指导服务。</td><td style="text-align:left;">2个技术支持 / 小时</td><td style="text-align:left;">提供在线文字咨询指导</td></tr><tr><td style="text-align:left;">视频/语音技术支持服务</td><td style="text-align:left;">本店软件领域相关技术问题的视频或语音实时指导、问题排查及解决方案落地等服务。</td><td style="text-align:left;">3个技术支持 / 小时</td><td style="text-align:left;">需提前预约服务时间</td></tr><tr><td style="text-align:left;">现场/上门技术支持服务</td><td style="text-align:left;">现场面对面提供技术指导、问题排查、部署调试，技术培训等全流程服务。</td><td style="text-align:left;">6个技术支持 / 小时</td><td style="text-align:left;">限北京地区，需提前1-2个工作日预约（4小时起）</td></tr><tr><td style="text-align:left;">定制类及其他服务</td><td style="text-align:left;">包括但不限于定制开发、技术对接、项目补差、服务续费等服务。</td><td style="text-align:left;">另行协商</td><td style="text-align:left;">请联系客服，沟通具体需求与方案后，再选择下单数量</td></tr></tbody></table><blockquote><p>💡 <strong>说明：</strong></p><ol><li>服务时长不足 1 小时按 1 小时计费；</li><li>技术支持 为基础计费单位（进入官方店铺：<a href="https://bima.taobao.com" target="_blank" rel="noreferrer">https://bima.taobao.com</a> 查看价格详情）；</li><li>预约类服务（视频 / 语音、上门）若取消，请提前 4 小时告知；</li><li>若上门服务已在路上被取消则需扣除 1 个技术支持费用；</li><li>上门服务时间按在客户现场实际服务时长计费，五环外无地铁直达需额外购买 2 个技术支持费用（ 1 小时）作为路程补贴，具体请提前与客服确认。</li></ol><p>（已下单的技术支持服务不支持退款但可更换时间）</p></blockquote><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如有合作意向或技术咨询需求，欢迎联系我们。</p><div class="contact-info"><div class="contact-item"><img src="'+s+'" class="vp-light-only" width="24" height="24"><img src="'+o+'" class="vp-dark-only" width="24" height="24"><span>官方网址：https://bima.cc</span></div></div><div class="contact-info"><div class="contact-item"><img src="'+r+'" class="vp-light-only" width="24" height="24"><img src="'+n+'" class="vp-dark-only" width="24" height="24"><span>官方店铺：https://bima.taobao.com</span></div></div><div class="contact-info"><div class="contact-item"><img src="'+d+'" class="vp-light-only" width="24" height="24"><img src="'+c+'" class="vp-dark-only" width="24" height="24"><span>联系邮箱：bima.cc@qq.com</span></div></div><div class="contact-info"><div class="contact-item"><img src="'+h+'" class="vp-light-only" width="24" height="24"><img src="'+g+'" class="vp-dark-only" width="24" height="24"><span>联系微信：e18929958</span></div></div>',27)])])}const u=a(f,[["render",p]]);export{S as __pageData,u as default};
